CREATE DATABASE IF NOT EXISTS taskflow CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE taskflow;
SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE academic_years(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(20) NOT NULL,is_active TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE semesters(id INT AUTO_INCREMENT PRIMARY KEY,academic_year_id INT NOT NULL,name VARCHAR(30) NOT NULL,is_active TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(academic_year_id) REFERENCES academic_years(id));
CREATE TABLE study_programs(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(10) NOT NULL,name VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(100) NOT NULL UNIQUE,identity_number VARCHAR(30) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','dosen','mahasiswa') NOT NULL,is_active TINYINT DEFAULT 1,photo VARCHAR(255),reset_token VARCHAR(64),reset_expires DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE classes(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(50) NOT NULL,study_program_id INT,semester_id INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(study_program_id) REFERENCES study_programs(id),FOREIGN KEY(semester_id) REFERENCES semesters(id));
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,class_id INT,study_program_id INT,semester INT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(class_id) REFERENCES classes(id),FOREIGN KEY(study_program_id) REFERENCES study_programs(id));
CREATE TABLE lecturers(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,study_program_id INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(study_program_id) REFERENCES study_programs(id));
CREATE TABLE courses(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(15) NOT NULL,name VARCHAR(100) NOT NULL,study_program_id INT,semester_id INT,lecturer_id INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(study_program_id) REFERENCES study_programs(id),FOREIGN KEY(semester_id) REFERENCES semesters(id),FOREIGN KEY(lecturer_id) REFERENCES lecturers(id));
CREATE TABLE course_enrollments(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,course_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(student_id,course_id),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE assignments(id INT AUTO_INCREMENT PRIMARY KEY,course_id INT NOT NULL,class_id INT,lecturer_id INT NOT NULL,title VARCHAR(150) NOT NULL,description TEXT,start_date DATETIME,deadline DATETIME NOT NULL,allowed_types VARCHAR(100) DEFAULT 'pdf,doc,docx,ppt,pptx,xls,xlsx,zip',max_size_mb INT DEFAULT 10,allow_late TINYINT DEFAULT 0,allow_resubmit TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE,FOREIGN KEY(class_id) REFERENCES classes(id),FOREIGN KEY(lecturer_id) REFERENCES lecturers(id));
CREATE TABLE assignment_attachments(id INT AUTO_INCREMENT PRIMARY KEY,assignment_id INT NOT NULL,file_name VARCHAR(255),stored_name VARCHAR(255),mime VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(assignment_id) REFERENCES assignments(id) ON DELETE CASCADE);
CREATE TABLE submissions(id INT AUTO_INCREMENT PRIMARY KEY,submission_no VARCHAR(30) NOT NULL UNIQUE,assignment_id INT NOT NULL,student_id INT NOT NULL,file_name VARCHAR(255),stored_name VARCHAR(255),file_size INT,note TEXT,status ENUM('Menunggu Penilaian','Sudah Dinilai','Perlu Revisi') DEFAULT 'Menunggu Penilaian',is_late TINYINT DEFAULT 0,submitted_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(assignment_id,student_id),FOREIGN KEY(assignment_id) REFERENCES assignments(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE submission_history(id INT AUTO_INCREMENT PRIMARY KEY,submission_id INT NOT NULL,file_name VARCHAR(255),stored_name VARCHAR(255),note TEXT,submitted_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(submission_id) REFERENCES submissions(id) ON DELETE CASCADE);
CREATE TABLE grades(id INT AUTO_INCREMENT PRIMARY KEY,submission_id INT NOT NULL UNIQUE,score INT,feedback TEXT,graded_by INT,graded_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(submission_id) REFERENCES submissions(id) ON DELETE CASCADE,FOREIGN KEY(graded_by) REFERENCES lecturers(id));
CREATE TABLE course_materials(id INT AUTO_INCREMENT PRIMARY KEY,course_id INT NOT NULL,lecturer_id INT NOT NULL,class_id INT,title VARCHAR(150) NOT NULL,description TEXT,meeting_no INT DEFAULT 1,publish_date DATE,video_url VARCHAR(255),reference_url VARCHAR(255),status ENUM('draft','published','hidden') DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE,FOREIGN KEY(lecturer_id) REFERENCES lecturers(id),FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE material_attachments(id INT AUTO_INCREMENT PRIMARY KEY,material_id INT NOT NULL,file_name VARCHAR(255),stored_name VARCHAR(255),mime VARCHAR(100),file_size INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(material_id) REFERENCES course_materials(id) ON DELETE CASCADE);
CREATE TABLE material_progress(id INT AUTO_INCREMENT PRIMARY KEY,material_id INT NOT NULL,student_id INT NOT NULL,completed_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(material_id,student_id),FOREIGN KEY(material_id) REFERENCES course_materials(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(150),message VARCHAR(255),is_read TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE announcements(id INT AUTO_INCREMENT PRIMARY KEY,author_id INT NOT NULL,title VARCHAR(150),body TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE activity_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,action VARCHAR(60),detail VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS personal_courses(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,code VARCHAR(15),name VARCHAR(100) NOT NULL,lecturer_name VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS personal_tasks(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,personal_course_id INT NULL,title VARCHAR(150) NOT NULL,description TEXT,deadline DATETIME NULL,status ENUM('Belum','Selesai') DEFAULT 'Belum',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(personal_course_id) REFERENCES personal_courses(id) ON DELETE SET NULL);
SET FOREIGN_KEY_CHECKS=1;
